<?php require_once __DIR__.'/inc/site.php'; begin_page("Dépannage : archives, assets et régions","Troubleshooting archives, assets and regions","Du symptôme à la cause probable, avec des vérifications concrètes avant toute réparation.","From symptom to probable cause, with concrete checks before attempting repairs.");
callout('Commence par relever les logs. Ne redémarre pas ou ne purge pas des données avant d’avoir conservé les premières erreurs pertinentes.','Start by checking logs. Do not restart or purge data before preserving the first relevant failures.');
echo '<p><a href="install-logs.php?lang='.e($lang).'">'.e(t('Guide des logs OpenSim et ROBUST','OpenSim and ROBUST log guide')).'</a></p>';
sec('L’OAR semble chargé mais les textures manquent','OAR loaded but textures are missing');p('Vérifiez si l’OAR a été créé avec --noassets, ou si --skip-assets a été employé lors du chargement. Contrôlez la disponibilité des UUID dans votre service assets et recherchez les avertissements dans les logs. Recommencez avec une archive complète si vous disposez des droits et des ressources.','Check whether the OAR was saved with --noassets or loaded with --skip-assets. Check referenced UUIDs in the asset service and warnings in logs. Retry with a full archive if you have the needed rights and files.');
diagnostic_steps({"logs":["OpenSim.log de la région de destination et Robust.log sur une grille ; en Standalone, journal OpenSim seulement.","Destination region OpenSim.log and central Robust.log for a grid; Standalone uses OpenSim.log."],"search":["Rechercher le nom de l'archive, UUID d'asset, erreurs de lecture/stockage et messages de chargement OAR ; les mots exacts varient selon la version.","Search the archive name, asset UUID, read/storage errors and OAR load events; exact messages vary by version."],"verify":["Comparer les options de l'import/export et tester la récupération d'un UUID auprès du service assets, sans modifier les données.","Compare import/export options and verify asset retrieval for a specific UUID without changing data."],"fix":["Si les assets ont réellement été exclus, réimporter une archive complète depuis une sauvegarde fiable, après protection du contenu cible.","If assets were intentionally excluded, use a complete trusted archive after backing up the target."]});
sample('grep -nEi \'asset|oar|archive|exception|error\' OpenSim.log | tail -n 80','Lecture seule : adapte les chemins, noms d\'unité et valeurs.','Read-only check: adapt paths, service names and values.');
sec('Les constructions sont déplacées ou hors de la région','Builds appear displaced or outside the region');p('Vérifiez d’abord SizeX/SizeY de la région, puis les options --displacement et --rotation. Vérifiez les limites de la destination avant réimportation. Un OAR ne redimensionne pas le fichier Regions.ini à votre place.','Check region SizeX/SizeY first, then --displacement and --rotation. Validate destination boundaries before reimporting. An OAR does not rewrite Regions.ini dimensions for you.');
diagnostic_steps({"logs":["OpenSim.log au moment de l’import OAR.","OpenSim.log during the OAR import."],"search":["Repérer l'opération de chargement et les éventuels avertissements de dimensions ou d'objets ignorés.","Locate the load operation and any warnings about dimensions or skipped objects."],"verify":["Comparer tailles source/destination, déplacements, rotation et coordonnées dans Regions.ini.","Compare source/destination sizes, displacement, rotation and Regions.ini coordinates."],"fix":["Refaire un essai sur une région de test avec les options corrigées après sauvegarde.","Retry on a test region with corrected options after backup."]});
sample('grep -nEi \'oar|rotation|displacement|region|warn|error\' OpenSim.log | tail -n 80','Lecture seule : adapte les chemins, noms d\'unité et valeurs.','Read-only check: adapt paths, service names and values.');
sec('Le chargement a remplacé des objets','Import replaced existing objects');p('Une restauration sans --merge peut remplacer une partie importante du contenu cible. Arrêtez les modifications, conservez les logs et revenez à une sauvegarde pré-import. N’essayez pas de réparer un effacement par des fusions successives non contrôlées.','A restore without --merge can replace substantial target content. Stop edits, retain logs and recover from the pre-import backup. Avoid uncontrolled additional merges.');
diagnostic_steps({"logs":["OpenSim.log de la région concernée, logs de sauvegarde si disponibles.","Affected region OpenSim.log and any backup job logs."],"search":["Chercher l'heure de l'import et les traces du chargement OAR ; vérifier les options réellement utilisées.","Find the import time and OAR loading messages; confirm the actual options used."],"verify":["Déterminer si --merge était absent et inventorier les sauvegardes antérieures.","Determine whether --merge was missing and inventory earlier backups."],"fix":["Stopper les modifications ; restaurer uniquement depuis un point cohérent validé sur un environnement de test.","Stop further changes; restore only a consistent snapshot validated on a test environment."]});
sample('grep -nEi \'oar|load|archive|error\' OpenSim.log | tail -n 100','Lecture seule : adapte les chemins, noms d\'unité et valeurs.','Read-only check: adapt paths, service names and values.');
sec('La sauvegarde IAR est incomplète','IAR backup is incomplete');p('Vérifiez le chemin de l’inventaire, les options --exclude et --excludefolder, les filtres --perm et la présence d’assets cassés. L’option --skipbadassets peut exclure des éléments problématiques ; elle n’est pas équivalente à une réparation.','Verify inventory path, --exclude and --excludefolder, --perm filters and missing assets. --skipbadassets may omit broken items; it is not a repair tool.');
diagnostic_steps({"logs":["OpenSim.log de l'instance traitant l'IAR et Robust.log si le service inventaire est distant.","OpenSim.log from the IAR processing instance and Robust.log if inventory is remote."],"search":["Chercher IAR, inventory, permission, asset, UUID et les erreurs de sérialisation.","Look for IAR, inventory, permission, asset, UUID and serialization errors."],"verify":["Comparer le chemin inventaire demandé, le contenu exporté et les options d'exclusion.","Compare requested inventory path, exported contents and exclusion flags."],"fix":["Refaire un export ciblé sans filtres non nécessaires ; ne pas considérer --skipbadassets comme une réparation.","Retry a targeted export without unnecessary filters; --skipbadassets is not a repair."]});
sample('grep -nEi \'iar|inventory|asset|permission|error\' OpenSim.log | tail -n 100','Lecture seule : adapte les chemins, noms d\'unité et valeurs.','Read-only check: adapt paths, service names and values.');
sec('Les assets étaient absents de l’archive IAR','Assets were omitted from an IAR');p('Un IAR créé avec --noassets conserve des références mais pas les données d’assets. La présence des mêmes assets sur le serveur cible conditionne le résultat. Réexportez avec assets depuis la source si elle est encore disponible.','An IAR created with --noassets retains references but not asset payloads. The target must already provide the referenced assets. Re-export with assets from the source if still possible.');
diagnostic_steps({"logs":["OpenSim.log au moment de l'export et lors de l'import ; Robust.log côté service assets si disponible.","OpenSim.log during export and import; Robust.log for remote asset services if available."],"search":["Rechercher IAR, asset not found, erreurs de récupération et UUID concernés ; le vocabulaire dépend de la version.","Search IAR events, missing-asset errors, retrieval failures and affected UUIDs; wording depends on version."],"verify":["Inspecter les options de sauvegarde et vérifier si le service de destination possède les UUID.","Inspect backup options and check whether the destination asset service has the UUIDs."],"fix":["Exporter de nouveau avec les assets depuis la source si possible.","Re-export with assets from the source if available."]});
sample('grep -nEi \'iar|asset|not found|error\' OpenSim.log | tail -n 100','Lecture seule : adapte les chemins, noms d\'unité et valeurs.','Read-only check: adapt paths, service names and values.');
sec('La modification INI n’a aucun effet','INI edit appears ineffective');p('Vérifiez que vous avez modifié le fichier actif et non un fichier .example. Recherchez les surcharges bin/config et les inclusions de config-include. Utilisez config show et contrôlez si un redémarrage est nécessaire.','Check that you edited the active file, not an .example template. Inspect bin/config overrides and config-include files. Use config show and check whether a restart is needed.');
diagnostic_steps({"logs":["OpenSim.log de l'instance ciblée ; Robust.log si l'option concerne les services centraux.","Target simulator OpenSim.log; Robust.log if the change concerns central services."],"search":["Chercher le chargement des fichiers de configuration, erreurs de parsing, clé ou section inconnue.","Find configuration file loading events, parse errors and unrecognized sections or keys."],"verify":["Comparer le fichier réellement chargé, les includes et la valeur effective via config show pour le simulateur.","Compare actual files, includes and effective configuration through simulator config show."],"fix":["Corriger uniquement le fichier actif et redémarrer le composant si le paramètre exige une relecture.","Correct only the active file and restart the relevant component if it requires configuration reload."]});
sample('grep -nEi \'config|ini|error|warn\' OpenSim.log | tail -n 80','Lecture seule : adapte les chemins, noms d\'unité et valeurs.','Read-only check: adapt paths, service names and values.');
sec('La région prend beaucoup de mémoire','Region memory usage is high');p('Mesurez l’évolution dans le temps et comparez l’activité. Contrôlez les caches, les scripts et les objets. Une valeur RSS élevée ne démontre pas à elle seule une fuite ; surveillez la croissance persistante à charge équivalente.','Measure the trend over time and compare equivalent activity. Check caches, scripts and objects. High RSS alone does not prove a leak; look for persistent growth at similar load.');
diagnostic_steps({"logs":["OpenSim.log et journaux système (OOM, kill, swap) ; statistiques d'utilisation mémoire.","OpenSim.log and system logs (OOM, kill, swap); memory metrics."],"search":["Chercher OutOfMemory, memory, GC ou terminaison soudaine, mais ne pas conclure à une fuite sur un seul RSS.","Look for OutOfMemory, memory, GC or abrupt termination; do not conclude a leak from one RSS snapshot."],"verify":["Comparer RSS et activité au fil du temps, scripts, physique, cache et swap.","Compare RSS and activity over time, scripts, physics, cache and swap."],"fix":["Isoler le sous-système responsable avant réglage ou redémarrage ; conserver les métriques.","Isolate the responsible subsystem before tuning or restarting; preserve metrics."]});
sample('grep -nEi \'memory|OutOfMemory|exception|fatal\' OpenSim.log | tail -n 80
journalctl -k --since \'1 hour ago\' | grep -Ei \'oom|killed process|out of memory\'','Lecture seule : adapte les chemins, noms d\'unité et valeurs.','Read-only check: adapt paths, service names and values.');
sec('Une téléportation reste lente','Teleports are slow');p('Contrôlez les logs des deux régions, la résolution DNS, les services ROBUST, la base de données, les communications réseau et les appels aux modules. Évitez d’attribuer automatiquement le problème au moteur physique.','Inspect source and destination region logs, DNS resolution, ROBUST services, database, network exchanges and module calls. Do not automatically blame the physics engine.');
diagnostic_steps({"logs":["OpenSim.log de la région source ET destination ; Robust.log sur une grille.","OpenSim.log from BOTH source and destination regions; Robust.log for a grid."],"search":["Chercher horodatages de transfert, timeout, failed, destination, agent et exceptions.","Find transfer timestamps, timeout, failed, destination, agent and exceptions."],"verify":["Aligner les horloges, comparer les étapes et chronométrer la phase la plus lente.","Align clocks, correlate stages and measure which phase is slowest."],"fix":["Corriger la couche fautive (réseau, services, région ou modules) plutôt que changer la physique au hasard.","Fix the failing layer (network, services, region or modules) rather than blindly changing physics settings."]});
sample('grep -nEi \'teleport|transfer|timeout|exception|failed\' OpenSim.log | tail -n 100','Lecture seule : adapte les chemins, noms d\'unité et valeurs.','Read-only check: adapt paths, service names and values.');
echo '<p><a href="https://opensimulator.org/wiki/Performance">OpenSimulator Wiki — Performance</a></p>';end_page();